/**
 * Typed access to the suburb dataset (data/suburbs.json, generated by scripts/pull-abs.ts).
 * Data only. Publishing/indexing decisions (status, brokerNote, reviewed) live elsewhere.
 */
import raw from "./data/suburbs.json";
import type { SuburbDataset, SuburbRecord } from "./types";

export type { SuburbDataset, SuburbRecord } from "./types";

export const suburbDataset = raw as unknown as SuburbDataset;
export const SUBURBS: readonly SuburbRecord[] = suburbDataset.suburbs;

/** Research §C4.1 gate: at least this many of the 14 field groups must be non-null to generate a page. */
export const MIN_COMPLETENESS = 10;

export function getSuburbBySlug(slug: string): SuburbRecord | undefined {
  return SUBURBS.find((s) => s.slug === slug);
}

export function getSuburbBySal(salCode: string): SuburbRecord | undefined {
  return SUBURBS.find((s) => s.salCode === salCode);
}

export function suburbsByBatch(batch: 1 | 2): SuburbRecord[] {
  return SUBURBS.filter((s) => s.batch === batch);
}

/** Suburbs that pass the data-completeness gate (does not check brokerNote / review). */
export function suburbsPassingDataGate(): SuburbRecord[] {
  return SUBURBS.filter((s) => s.completeness.score >= MIN_COMPLETENESS);
}

/**
 * Nearest suburbs restricted to an allow-list (e.g. published slugs), nearest first.
 * Research §C4.1 shows 3–5.
 */
export function nearestPublished(s: SuburbRecord, publishedSlugs: ReadonlySet<string>, max = 5) {
  return s.nearest.filter((n) => publishedSlugs.has(n.slug)).slice(0, max);
}
